from django.db import migrations, models


def copiar_licencas_para_contas(apps, schema_editor):
    """Leva as licenças da época da Kiwify pra ContaAppfiliado mantendo a mesma chave
    (assim quem já usa o app não precisa reativar). Licença ativa vira cortesia do
    módulo de WhatsApp - era o único que existia. Se o mesmo e-mail tiver mais de uma
    licença, fica a ativa mais recente."""
    Licenca = apps.get_model("licencas", "Licenca")
    ContaAppfiliado = apps.get_model("licencas", "ContaAppfiliado")
    licencas = sorted(
        Licenca.objects.all(),
        key=lambda l: (l.status == "ativa", l.criada_em),
        reverse=True,
    )
    for licenca in licencas:
        email = (licenca.email or "").strip().lower()
        if not email or ContaAppfiliado.objects.filter(email=email).exists():
            continue
        ContaAppfiliado.objects.create(
            email=email,
            nome=licenca.nome,
            chave=licenca.chave,
            chave_enviada_em=licenca.criada_em,
            modulos_cortesia="whatsapp" if licenca.status == "ativa" else "",
        )


